sys_script.script:
(function executeRule(current, previous /*null when async*/) {
	//gs.info("ARK00");
	// Add your code here
	var delayRelance=gs.getProperty('x_hpug_demande_a_0.delay_fin_droits');  // x_hpug_demande_a_0.delay_fin_droits
	var delayNotif=gs.getProperty('x_hpug_demande_a_0.delay_to_contact_resp'); // x_hpug_demande_a_0.delay_to_contact_resp
	//var dateCalculee=current.date_de_debut_souhaitee+delayRelance-delayNotif;
	var dateCalculee;

	var dateNew = new GlideDateTime(current.date_de_debut_souhaitee);
	dateNew.addDaysUTC(delayRelance);

	current.date_de_cloture=dateNew;

	//gs.info("ARK1"+"\nDate debut droit = "+current.date_de_debut_souhaitee+"\nNb de jours pour la relance = "+delayRelance+"\nNb de jour avant la relance = "+delayNotif+"\nDate calculee d envoi mail = "+dateNew);

	dateNew.addDaysUTC(-delayNotif);
	dateCalculee=dateNew;
	current.date_de_relance=dateCalculee;

	//gs.info("ARK2"+"\nDate debut droit = "+current.date_de_debut_souhaitee+"\nNb de jours pour la relance = "+delayRelance+"\nNb de jour avant la relance = "+delayNotif+"\nDate calculee d envoi mail = "+dateCalculee);

})(current, previous);
